const body = $json.body || {};
const employeeId = body.employeeId;
const pushToken = body.pushToken;

if (!employeeId || !pushToken) {
  return {
    json: {
      isValid: false,
      error: 'Missing required employeeId or pushToken in request body'
    }
  };
}

return {
  json: {
    isValid: true,
    employeeId: String(employeeId).trim(),
    role: (body.role || 'EMPLOYEE').toUpperCase(),
    pushToken: String(pushToken).trim(),
    fcmToken: body.fcmToken || null,
    platform: body.platform || 'android',
    deviceName: body.deviceName || 'Android Device',
    appVersion: body.appVersion || '1.0.0'
  }
};
